def find_size(puzzle, x, y, end_x, end_y, x1, y1):
    for row in range(y, end_y):
        for col in range(x, end_x):
            if puzzle[row][col] == 0:
                break
            size = find_size(puzzle, col+1, row+1, end_x-1, end_y-1)
        for row in reversed(range(y1, row+1)):
            for lower_row in reversed(range(y1, row+1)):
                for col in range(x, end_x):
