    total_cost = 0
    stock_count = [0] * (2 * n)
    for x, y in exchanges:
        total_cost += x * exchanges_count - x
        stock_count[y] += x
    return total_cost == 0 and stock_count[n] == 1

def find_optimal_time(n, stocks):
    n *= 2
    exchanges = []
    smallest = inf
    largest = -inf
    exchanges_count = [0] * n
    for i in range(len(stocks)):
        price = stocks[i][1]
        if i < n // 2:
            smallest = min(smallest, price)
        else:
            largest = max(largest, price)
        for j in range(n):
            heappush(exchanges, (price + j * (i + 1), j))
            exchanges_count[j] += 1
    while len(exchanges) > 0:
        (cost, stock) = heappop(exchanges)
        if smallest <= cost <= largest:
            exchanges_count[stock] -= 1
            if exchanges_count[stock] == 0:
                exchanges_count[stock] += 1
                stam = None if stock == n else -1
                for ex in exchanges:
                    if stock == -1:
                        ex[1] += stam
                    else:
                        heappush(exchanges, (ex[1], ex[0] + ex[1]))
                return len(exchanges)
    return -1

