            elif weights > cap[cur_v][i]:
                weights = cap[cur_v][i]

            if d[i] < 0 or (d[i] == d[cur_v] + weights and cost[cur_v][i] > cost[cur_v][prev[cur_v]] + cost[prev[cur_v]][i] + d[cur_v]):
                costs[i] = d[cur_v] + weights
                prev[i] = cur_v
                heappush(q, (abs(cur_w - cost[cur_v][i] - d[cur_v]), i))

                if d[i] == d[cur_v] + weights:
