from math import comb

def query(n, k):
    if k > n:
        return 1

    mod = 1000000007
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        for j in range(i):
            if i - j - 1 in range(j + 1, k + 1):
                dp[i] = (dp[i - 1] + dp[j] * comb(k - j, j)) % mod

    return dp[n]

