from math import pow

def count_few_sets(n, k):
    if n < k:
        return 0
    elif k == 0:
        return 1
    elif n == k:
        return pow(2, n)

    mod = 1000000007
    partitions_count = 0

    for i in range(k + 1):
        # Calculate the number of ways to choose partitions up to i plus the remaining partitions
        partitions_count += pow(2, n - i) * factorial(n - i) % mod
        partitions_count %= mod

    return partitions_count

def factorial(num):
    if num == 0:
        return 1
    fact = 1
    for i in range(1, num + 1):
        fact *= i
    return fact

