import random

def find_LIS(arr):
    LIS = [1] * len(arr)
    for i in range(1, len(arr)):
        for j in range(i):
            if arr[i] > arr[j] and LIS[i] < LIS[j] + 1:
                LIS[i] = LIS[j] + 1
    return max(LIS)

def canonical_permutation(arr):
    s = sum(arr)
    total = 0
    for i in arr:
        total += i
    remain = len(arr)
    for i in arr:
        k = remain % i
        remain -= i
        remain += k
        yield k
    yield total - sum(range(s))

def split_and_permute(A, K):
    N = len(A)
    P = list(range(K))
    permutations = list(canonical_permutation(A))
    B = [A[-1]] * N
    for s, p in zip(A, permutations):
        B[p] = s
    for i in range(K-1, 0, -1):
        indices = [j for j, num in enumerate(B) if B[indices[i]] < B[indices[i-1]]]
        for p in range(i):
            if indices[p] < indices[p+1]:
                indices[p] = indices[p+1]
            else:
                break
        for j in indices:
            B[j] = B[indices[i]]    
    return B

N, K = map(int, input().split())
A = list(map(int, input().split()))
B = split_and_permute(A, K)
print(' '.join(map(str, B)))
