from collections import defaultdict, deque

def find_parent(parent, x):
    if parent[x] == x:
        return x
    return find_parent(parent, parent[x])

def union_parent(parent, a, b):
    a.set_parent(find_parent(parent, a))
    b.set_parent(find_parent(parent, b))

def solution(n, edges):
    edge_dict = defaultdict(list)
    parent = {}
    min_set = set(range(1, n + 1))

    for a, b, s in edges:
        edge_dict[a].append((b, s))
        edge_dict[b].append((a, s))

    for node in edge_dict:
        edge_dict[node].sort(key=lambda x: x[1])

    for node in edge_dict:
        parent[node] = node

    total_sum = 0
    for node in edge_dict:
        for neighbor, length in edge_dict[node]:
            if len(min_set.difference({find_parent(parent, node), find_parent(parent, neighbor)})) > 2:
                total_sum += length
                union_parent(parent, node, neighbor)
                min_set.discard(neighbor)
                min_set.discard(find_parent(parent, neighbor))

    return total_sum

n = int(input())
edges = []
for _ in range(n - 1):
    u, v, w = map(int, input().split())
    edges.append((u, v, w))

result = solution(n, edges)
print(result)
