import math

def minimum_string_after_operations(s):
    n = len(s)
    power = 0
    result = [i for i in s]
    done = [False] * n

    while sum(done) != n:
        if power % 2 == 0:
            while True:
                found = False
                for i in range(n):
                    if not done[i] and s[i] < result[i]:
                        result[i] = s[i]
                        done[i] = True
                        index_new = i + math.floor(math.pow(2, power) - 1)
                        if index_new >= n:
                            return ''.join(result)
                        result[index_new] = s[index_new]
                        result[i+1] = ''
                        found = True
                        break
                if not found:
                    break
        else:
            past_even = [i for i in s if not done[i]]
            index_new = past_even[0] + math.floor(math.pow(2, power) - 1)
            result[0] = past_even[-1]
            result[index_new:] = [s[p] for p in range(index_new, n, 1)]
            return ''.join(result)

    return ''.join(result)

# Example usage:
s = "adcbca"
print(minimum_string_after_operations(s))  # Output: "aba"
